        ("Vm.UnavailablePrefixWasBuiltByProton", "Indisponível: este prefixo foi criado pelo Proton {0}, que não está mais instalado, e o Wine do sistema poderia danificá-lo. Reinstale esse Proton e atualize a biblioteca.", "Unavailable: this prefix was built by Proton {0}, which is no longer installed, and system Wine could damage it. Reinstall that Proton and refresh the library."),
        ("Vm.WinetricksUnavailablePrefixWasBuiltBy", "Winetricks indisponível: este prefixo foi criado pelo Proton {0}, que não está mais instalado, e o Wine do sistema poderia danificá-lo. Reinstale esse Proton (ou escolha um instalado no launcher) e atualize a biblioteca.", "Winetricks unavailable: this prefix was built by Proton {0}, which is no longer installed, and system Wine could damage it. Reinstall that Proton (or choose an installed one in the launcher) and refresh the library."),
        ("Vm.RHIUndidInstallSInterruptedBy", "RHI desfez {0} instalação(ões) interrompida(s) por um encerramento inesperado; os arquivos voltaram ao estado anterior.", "RHI undid {0} install(s) interrupted by an unexpected shutdown; the files are back as they were."),
        ("Vm.RHIUndidInterruptedInstallSBut", "RHI desfez {0} instalação(ões) interrompida(s), mas manteve arquivos ou ajustes alterados depois do encerramento; as cópias anteriores do RHI estão em .rhi-recovered ao lado deles. Detalhes: {1}", "RHI undid {0} interrupted install(s) but kept files or settings changed after the shutdown; RHI's earlier copies are in .rhi-recovered next to them. Details: {1}"),
        ("Vm.RHICouldNotUndoInterruptedInstall", "RHI não conseguiu desfazer {0} instalação(ões) interrompida(s) e tentará de novo na próxima abertura. Detalhes: {1}", "RHI could not undo {0} interrupted install(s) and will try again at the next start. Details: {1}"),
        ("Vm.InterruptedInstallSWillFinishedAt", "{0} instalação(ões) interrompida(s) serão concluídas numa próxima abertura (registro de implantações ilegível ou Wine em execução no prefixo). Detalhes: {1}", "{0} interrupted install(s) will be finished at a later start (deployment ledger unreadable, or Wine running in the prefix). Details: {1}"),
        ("Vm.RHISetAsideOldCopyIes", "RHI guardou {0} cópia(s) antiga(s) que não pôde provar redundantes em .rhi-recovered, na mesma pasta. Detalhes: {1}", "RHI set aside {0} old copy(ies) it could not prove redundant in .rhi-recovered in the same folder. Details: {1}"),
        ("Vm.CacheCouldNotReadWillRebuilt", "O cache {0} não pôde ser lido e será recriado.", "The cache {0} could not be read and will be rebuilt."),
