        ("Vm.CouldNotReadCopiedRHIWill", "{0} não pôde ser lido nem copiado ({1}). O RHI não vai salvar por cima dele: corrija ou apague o arquivo para voltar a salvar.", "{0} could not be read or copied ({1}). RHI will not save over it: fix or delete the file to save again."),
        ("Vm.CouldNotReadItsContentsWere", "{0} não pôde ser lido; o conteúdo foi copiado para {1}. O RHI não vai salvar por cima dele: corrija ou apague o arquivo para voltar a salvar.", "{0} could not be read; its contents were copied to {1}. RHI will not save over it: fix or delete the file to save again."),
        ("Vm.NotSavedCouldNotReadCopy", "Não salvo: {0} não pôde ser lido (há uma cópia em {1}). Corrija ou apague o arquivo para voltar a salvar.", "Not saved: {0} could not be read (a copy is at {1}). Fix or delete the file to save again."),
